export interface TechNode {
	id: ProgressionTreeNodeType;
	name: string;
	icon: string;
	turns: number;
	treeType: ProgressionTreeType;
	unlocksByDepth: ChooserDepthInfo[];
	recommendations: AdvisorRecommendations[];
	isLocked?: boolean;
	cost: number;
	progress: number;

	/** The current depth index being researched (0-based). */
	currentDepthIndex: number;
}

/**
 * Build a TechNode data object for display in the chooser.
 * @param player - The player library.
 * @param nodeType - The progression tree node type.
 * @param isActiveResearch - Whether this node is currently being actively researched.
 * @returns The TechNode data or null if the node data is not available.
 */
function buildTechNodeData(
	player: PlayerLibrary,
	nodeType: ProgressionTreeNodeType,
	isActiveResearch = false,
): TechNode | null {
	const nodeDef = GameInfo.ProgressionTreeNodes.lookup(nodeType);
	const nodeData = Game.ProgressionTrees.getNode(player.id, nodeType);
	if (!nodeDef || !nodeData) return null;

	const unlocksByDepth: ChooserDepthInfo[] = [];

	const treeNodeUnlocks = TreeNodesSupport.getValidNodeUnlocks(nodeData);
	const removableUnlocks = TreeNodesSupport.getRepeatedUniqueUnits(treeNodeUnlocks);

	for (const idx of nodeData.unlockIndices) {
		const unlockInfo = GameInfo.ProgressionTreeNodeUnlocks[idx];
		if (!unlockInfo || unlockInfo.Hidden) continue;

		// Filter disabled/repeated units
		if (unlockInfo.TargetKind === "KIND_UNIT") {
			const p = Players.get(GameContext.localPlayerID);
			if (p && p.Units?.isBuildPermanentlyDisabled(unlockInfo.TargetType)) continue;
			if (removableUnlocks.includes(unlockInfo.TargetType)) continue;
		}

		const unlockDisplayData = buildUnlockDisplayData(unlockInfo);
		const hasInfo = unlockDisplayData.nameKey.length > 0 || hasUnlockContent(unlockDisplayData.descriptionData);
		if (!hasInfo) continue;

		while (unlocksByDepth.length < unlockInfo.UnlockDepth) {
			const depthIndex = unlocksByDepth.length;
			const isCompleted = depthIndex < nodeData.depthUnlocked;
			const isCurrent = isActiveResearch && depthIndex === nodeData.depthUnlocked;
			unlocksByDepth.push({
				header: "",
				unlocks: [],
				isCompleted,
				isCurrent,
				isLocked: false,
			});
		}
		const depthIdx = unlockInfo.UnlockDepth - 1;
		if (unlockDisplayData.icon) {
			unlocksByDepth[depthIdx].unlocks.push(unlockDisplayData);
		}
	}

	const techRecommendations = AdvisorUtilities.getTreeRecommendations(AdvisorySubjectTypes.CHOOSE_TECH);
	const recommendations = AdvisorUtilities.getTreeRecommendationIcons(techRecommendations, nodeType).map(
		(rec: { class: AdvisorRecommendations }) => rec.class,
	);

	const playerTechs = player?.Techs;

	const cost = playerTechs?.getNodeCost(nodeType) ?? -1;
	const turns = playerTechs?.getTurnsForNode(nodeType) ?? -1;

	return {
		id: nodeType,
		name: getNodeName(nodeData, player),
		icon: GameIcon.getTechIconFromProgressionTreeNodeDefinition(nodeDef),
		turns,
		treeType: nodeDef.ProgressionTree,
		unlocksByDepth,
		recommendations,
		isLocked: false,
		cost: cost,
		progress: nodeData.progress ?? 0,
		currentDepthIndex: nodeData.depthUnlocked,
	};
}

/**
 * Get the currently active (in-progress) tech node type, if any.
 */
function getActiveNodeType(player: PlayerLibrary): ProgressionTreeNodeType | undefined {
	const techTreeType = player?.Techs?.getTreeType();
	if (techTreeType === undefined) return undefined;
	const treeObject = Game.ProgressionTrees.getTree(player.id, techTreeType);
	return treeObject?.nodes?.[treeObject.activeNodeIndex]?.nodeType;
}

/**
 * Get all available tech nodes for the player.
 * The active node (if any) will have its isCurrent flags set appropriately.
 */
function getAllTechNodes(player: PlayerLibrary): TechNode[] {
	const out: TechNode[] = [];
	const available = player?.Techs?.getAllAvailableNodeTypes?.();
	if (!available) return out;

	const activeNodeType = getActiveNodeType(player);

	for (const nodeType of available) {
		const isActiveResearch = nodeType === activeNodeType;
		const node = buildTechNodeData(player, nodeType, isActiveResearch);
		if (node) out.push(node);
	}
	return out;
}

function chooseTech(nodeId: ProgressionTreeNodeType) {
	const nodeIndex = nodeId;
	const args = { ProgressionTreeNodeType: nodeIndex };
	const result = Game.PlayerOperations.canStart(
		GameContext.localPlayerID,
		PlayerOperationTypes.SET_TECH_TREE_NODE,
		args,
		false,
	);
	if (result?.Success) {
		Game.PlayerOperations.sendRequest(GameContext.localPlayerID, PlayerOperationTypes.SET_TECH_TREE_NODE, args);
	}
}

function openFullTree(defaultNode?: ProgressionTreeNodeType, treeType?: ProgressionTreeType) {
	const treeParent = (document.querySelector(".fxs-trees") as HTMLElement) || undefined;
	ContextManager.push("screen-tech-tree", { singleton: true, createMouseGuard: true, targetParent: treeParent });
	if (treeType !== undefined) {
		window.dispatchEvent(
			new CustomEvent("view-tech-progression-tree", {
				detail: {
					treeCSV: treeType,
					targetNode: defaultNode,
					iconCallback: GameIcon.getTechIconFromProgressionTreeNodeDefinition,
				},
			}),
		);
	}
	ContextManager.pop("screen-tech-tree-chooser");
}

const TechTreeChooser = () => {
	// a flag to determine if we should reset the input context on cleanup
	// this primarily exists to prevent resetting the input context to the world when opening the full tree
	let resetInputContext = true;
	const [getClosing, setClosing] = createSignal(false);
	const [allNodes, mutateNodes] = createArraySignal<TechNode>([]);
	const inProgressNode = createMemo(() => {
		const nodes = allNodes();
		for (const node of nodes) {
			const currentDepth = node.unlocksByDepth[node.currentDepthIndex];
			if (currentDepth?.isCurrent) return node;
		}
		return undefined;
	});

	const defaultNode = createMemo<ProgressionTreeNodeType | undefined>(
		() => inProgressNode()?.id ?? allNodes()[0]?.id,
	);
	const defaultTree = createMemo<ProgressionTreeType | undefined>(
		() => inProgressNode()?.treeType ?? allNodes()[0]?.treeType,
	);

	function refresh() {
		const player = Players.get(GameContext.localPlayerID);
		if (!player) return;
		const nodes = getAllTechNodes(player);
		mutateNodes((arr) => {
			arr.length = 0;
			arr.push(...nodes);
		});
	}

	function handleSelect(id: ProgressionTreeNodeType) {
		chooseTech(id);
		const args = { ProgressionTreeNodeType: ProgressionTreeNodeTypes.NO_NODE };
		Game.PlayerOperations.sendRequest(
			GameContext.localPlayerID,
			PlayerOperationTypes.SET_TECH_TREE_TARGET_NODE,
			args,
		);
		setClosing(true);
	}

	function handleOpenFullTree() {
		resetInputContext = false;
		openFullTree(defaultNode(), defaultTree());
	}

	onMount(() => {
		refresh();

		type EnginePlayerEvent = { player?: PlayerId } | undefined;
		const listener = (data: EnginePlayerEvent) => {
			if (data?.player !== undefined && data.player !== GameContext.localPlayerID) return;
			refresh();
		};
		UI.sendAudioEvent("tech-tree-chooser-panel-showing");
		const events = [
			"ScienceYieldChanged",
			"TechTreeChanged",
			"TechTargetChanged",
			"TechNodeCompleted",
			"PlayerTurnActivated",
			"LocalPlayerTurnBegin",
			"LocalPlayerChanged",
		] as const;
		for (const e of events) engine.on(e, listener);

		onCleanup(() => {
			for (const e of events) engine.off(e, listener);
			if (resetInputContext) {
				Input.setActiveContext(ViewManager.current.getInputContext());
			}
			// Really it should be this: "tech-tree-chooser-panel-hiding"
			// But we should make that change in Wwise first so it sounds correct.
			UI.sendAudioEvent("culture-tree-chooser-panel-hiding");
		});
	});

	return (
		<SidebarChooser
			context="screen-tech-tree-chooser"
			title="LOC_UI_TECH_CHOOSER_TITLE"
			id="tech-tree-chooser"
			name="tech-tree-chooser"
			closeButtonAudioGroup="audio-screen-tech-tree-chooser"
			closing={getClosing()}
		>
			<InnerFrame class="my-1\.5">
				<div class="tech-tree-currently-studying self-center w-96">
					<div class="text-accent-4 uppercase mt-1 font-title text-sm tracking-100">
						<L10n.Compose text="LOC_UI_CURRENT_TECH_HEADER" />
					</div>
					<div class="filigree-divider-inner-frame w-72 my-1\.5 self-center" />

					<Show
						when={inProgressNode()}
						fallback={
							<div class="w-full min-h-16 flex justify-center items-center font-body text-sm text-accent-4 text-center">
								<L10n.Compose text="LOC_UI_TECH_RESEARCH_EMPTY" />
							</div>
						}
					>
						{(node) => (
							<TechChooserItem
								node={node()}
								onSelect={handleSelect}
							/>
						)}
					</Show>
				</div>
			</InnerFrame>

			<div class="mt-4 mb-2\.5 font-title text-base w-96 self-center uppercase text-center">
				<L10n.Compose text="LOC_UI_TECH_AVAILABLE_HEADER" />
			</div>
			<ScrollArea class="flex-1">
				<For each={allNodes()}>
					{(node) => (
						<TechChooserItem
							node={node}
							onSelect={handleSelect}
						/>
					)}
				</For>
			</ScrollArea>

			<Button
				name="OpenFullTree"
				class="mx-8 mt-3 mb-6 uppercase"
				classList={{
					hidden: IsControllerActive(),
				}}
				audio={{
					group: "audio-screen-tech-tree-chooser",
					onFocus: "tech-tree-chooser-focus",
				}}
				disableFocus={IsControllerActive()}
				hotkeyAction="shell-action-1"
				navTrayText="LOC_UI_TECH_VIEW_FULL_PROG_TREE"
				onActivate={handleOpenFullTree}
			>
				<L10n.Compose text="LOC_UI_TECH_VIEW_FULL_PROG_TREE" />
			</Button>
		</SidebarChooser>
	);
};

window.addEventListener("hotkey-open-techs", () => {
	if (ContextManager.isCurrentClass("screen-tech-tree-chooser")) {
		ContextManager.pop("screen-tech-tree-chooser");
	} else {
		ContextManager.push("screen-tech-tree-chooser", { singleton: true });
	}
});

defineLegacyComponent(
	"screen-tech-tree-chooser",
	{
		classNames: ["screen-tech-tree-chooser", "flex"],
		tabIndex: 0,
	},
	(_attrs, _element) => {
		Input.setActiveContext(InputContext.Shell);
		return <TechTreeChooser />;
	},
);

ComponentUtilities.loadStyles(style);
